import pandas as pd
from pyspark.sql import functions as F


@F.pandas_udf("double")
def in_millions(volume: pd.Series) -> pd.Series:
    return volume / 1_000_000


@F.pandas_udf("long")
def rows_in_call(volume: pd.Series) -> pd.Series:
    return pd.Series([len(volume)] * len(volume))


daily_prices.select(
    "symbol", "trade_date", "volume",
    in_millions("volume").alias("volume_m"),
    rows_in_call("volume").alias("rows_in_call"),
).show()

