import pandas as pd
from pyspark.sql import functions as F


@F.pandas_udf("double")
def close_position(high: pd.Series, low: pd.Series, close: pd.Series) -> pd.Series:
    h = high.astype("float64")
    l = low.astype("float64")
    c = close.astype("float64")
    return ((c - l) / (h - l)).round(2)


daily_prices.select(
    "symbol", "trade_date", "low", "high", "close",
    close_position("high", "low", "close").alias("close_position"),
).show()
